1: //! Draw-list assembly: gather what should be drawn, in layer order.
2: 
3: use crate::entity::EntityId;
4: use crate::world::World;
5: use crate::{Hidden, Position, Sprite};
6: 
7: /// Build the draw list: every entity with a Position and a Sprite, sorted by
8: /// layer then by entity index for a stable order.
9: ///
10: /// Hidden entities keep their Sprite but must not draw, so — as in `physics` —
11: /// the exclusion is collected and filtered by hand.
12: pub fn draw_list(world: &World) -> Vec<(EntityId, i32)> {
13:     let hidden: Vec<EntityId> = world.iter::<Hidden>().map(|(id, _)| id).collect();
14:     let mut out: Vec<(EntityId, i32)> = world
15:         .iter2::<Position, Sprite>()
16:         .filter(|(id, _, _)| !hidden.contains(id))
17:         .map(|(id, _, s)| (id, s.layer))
18:         .collect();
19:     out.sort_by_key(|(id, layer)| (*layer, id.index));
20:     out
21: }

